-- Trivi-Yeah II: 5 new categories (GEOGRAPHY, TECHNOLOGY, FOOD_AND_DRINK,
-- MYTHOLOGY, LITERATURE), 20 questions each (4 tiers x 5), bringing the
-- regular board's category count from 5 to 10. Requires the matching code
-- change in src/services/gameEngine.js's TRIVI_YEAH_II_CATEGORIES array --
-- without that, these rows just sit in the table unused, same as
-- FINAL_WAGER's own category key does on purpose.
--
-- Why 10 categories: each round draws 3 of them at random, and a full
-- game plays 3 rounds -- with only 5 categories, the same one often came
-- up twice in a single game. 10 is enough that repeats within a game
-- become uncommon without the authoring burden of going much higher; see
-- chat for the full reasoning. Schema notes are in
-- trivi_yeah_ii_more_questions.sql -- same rules apply here.

INSERT INTO questions (question_number, game_mode, category, subcategory, faction, question_text, visual_asset, correct_answer, wrong_answers, points)
